window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a58e080597ac3e16"]={"versions": [{"id": "FIG-a58e080597ac3e16", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilverarbeitungsschritts innerhalb des E2E-Profils 7m (AUTOSAR End-to-End Communication Protection, Classic & Adaptive Platform). Dargestellt ist der Teilschritt „Write Message Type“ der Schutzfunktion <code>E2E_P07mProtect()</code>, eingebettet in die Serialisierung bzw. Absicherung von Botschaften mit E2E-Header-Informationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätsbereich / Kontext:</strong> Funktion <code>E2E_P07mProtect()</code> (gekennzeichnet über das abgerundete Label-Element oben links).</li>\n<li><strong>Startknoten (Initial Node):</strong> Ausgefüllter schwarzer Kreis zur Einleitung des Kontrollflusses.</li>\n<li><strong>Aktionsknoten (Action Node):</strong> Abgerundetes Rechteck mit der Zuordnungs- und Berechnungslogik:</li>\n<li>Text: <code>Copy 2-bit MessageType to bits 0 and 1 of byte Data[Offset+20] in Big Endian order, i.e., Data[Offset+20] = (Data[Offset+20] &amp; 0x3F) | ((messageType &amp; 0x03) &lt;&lt; 6)</code></li>\n<li><strong>Endknoten (Activity Final Node):</strong> Umrandeter Kreis mit zentriertem Punkt.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li>Eingangsgröße: 2-Bit-Wert <code>messageType</code>.</li>\n<li>Speicherziel / Array: <code>Data[]</code> ab Basisposition <code>Offset + 20</code>.</li>\n<li>Kontrollflusskanten (Control Flows): Gerichtete Pfeile vom Startknoten zur Aktion und von der Aktion zum Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung des Teilschritts beginnt am Startknoten und geht unmittelbar auf den Aktionsknoten über.</li>\n<li>Im Aktionsknoten werden die zwei Bits des Parameters <code>messageType</code> in die Bits 0 und 1 des Bytes <code>Data[Offset+20]</code> (gemäß Big-Endian-Bitnummerierung mit MSB als Bit 0) geschrieben.</li>\n<li>Die Bitmanipulation maskiert zunächst das Zielbyte <code>Data[Offset+20]</code> mit <code>0x3F</code> (Löschen der oberen beiden Bits 7 und 6 in Standard-Bitlogik bzw. Bits 0 und 1 in Big-Endian-Notation), maskiert <code>messageType</code> auf 2 Bit (<code>0x03</code>), verschiebt diesen Wert um 6 Positionen nach links (<code>&lt;&lt; 6</code>) und verknüpft das Ergebnis bitweise per ODER (<code>|</code>) mit dem maskierten Zielbyte.</li>\n<li>Nach Abschluss der Zuweisung folgt der Kontrollfluss dem ausgehenden Pfeil und terminiert am Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Verbindlichkeit:</strong> Das Diagramm spezifiziert verbindlich das exakte Bit-Mapping und die Arithmetik für das Feld <code>MessageType</code> innerhalb von Byte 20 des geschützten Datenpuffers (<code>Data[Offset+20]</code>) für E2E Profile 7m gemäß Anforderung <code>[PRS_E2E_00806]</code>.</li>\n<li><strong>Implementierungshinweise:</strong></li>\n<li>Entwickler müssen beachten, dass die textuelle Beschreibung „bits 0 and 1 in Big Endian order“ sich direkt in der C-äquivalenten Bitmaskierungs- und Shift-Operation <code>(Data[Offset+20] &amp; 0x3F) | ((messageType &amp; 0x03) &lt;&lt; 6)</code> widerspiegelt, wobei Bit 0 dem MSB (Wertigkeit <code>0x80</code>) und Bit 1 der Wertigkeit <code>0x40</code> entspricht.</li>\n<li>Etwaige zuvor in <code>Data[Offset+20]</code> an den Bits 2 bis 7 enthaltene Daten (wie z. B. Message Result oder SourceID-Anteile) bleiben durch die Maskierung mit <code>0x3F</code> unverändert erhalten.</li>\n</ul>"}, {"id": "FIG-233c3604ea61634a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilverarbeitungsschritts innerhalb des E2E-Profils 7m (AUTOSAR End-to-End Communication Protection, Classic & Adaptive Platform). Dargestellt ist der Teilschritt „Write Message Type“ der Schutzfunktion <code>E2E_P07mProtect()</code>, eingebettet in die Serialisierung bzw. Absicherung von Botschaften mit E2E-Header-Informationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätsbereich / Kontext:</strong> Funktion <code>E2E_P07mProtect()</code> (gekennzeichnet über das abgerundete Label-Element oben links).</li>\n<li><strong>Startknoten (Initial Node):</strong> Ausgefüllter schwarzer Kreis zur Einleitung des Kontrollflusses.</li>\n<li><strong>Aktionsknoten (Action Node):</strong> Abgerundetes Rechteck mit der Zuordnungs- und Berechnungslogik:</li>\n<li>Text: <code>Copy 2-bit MessageType to bits 0 and 1 of byte Data[Offset+20] in Big Endian order, i.e., Data[Offset+20] = (Data[Offset+20] &amp; 0x3F) | ((messageType &amp; 0x03) &lt;&lt; 6)</code></li>\n<li><strong>Endknoten (Activity Final Node):</strong> Umrandeter Kreis mit zentriertem Punkt.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li>Eingangsgröße: 2-Bit-Wert <code>messageType</code>.</li>\n<li>Speicherziel / Array: <code>Data[]</code> ab Basisposition <code>Offset + 20</code>.</li>\n<li>Kontrollflusskanten (Control Flows): Gerichtete Pfeile vom Startknoten zur Aktion und von der Aktion zum Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung des Teilschritts beginnt am Startknoten und geht unmittelbar auf den Aktionsknoten über.</li>\n<li>Im Aktionsknoten werden die zwei Bits des Parameters <code>messageType</code> in die Bits 0 und 1 des Bytes <code>Data[Offset+20]</code> (gemäß Big-Endian-Bitnummerierung mit MSB als Bit 0) geschrieben.</li>\n<li>Die Bitmanipulation maskiert zunächst das Zielbyte <code>Data[Offset+20]</code> mit <code>0x3F</code> (Löschen der oberen beiden Bits 7 und 6 in Standard-Bitlogik bzw. Bits 0 und 1 in Big-Endian-Notation), maskiert <code>messageType</code> auf 2 Bit (<code>0x03</code>), verschiebt diesen Wert um 6 Positionen nach links (<code>&lt;&lt; 6</code>) und verknüpft das Ergebnis bitweise per ODER (<code>|</code>) mit dem maskierten Zielbyte.</li>\n<li>Nach Abschluss der Zuweisung folgt der Kontrollfluss dem ausgehenden Pfeil und terminiert am Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Verbindlichkeit:</strong> Das Diagramm spezifiziert verbindlich das exakte Bit-Mapping und die Arithmetik für das Feld <code>MessageType</code> innerhalb von Byte 20 des geschützten Datenpuffers (<code>Data[Offset+20]</code>) für E2E Profile 7m gemäß Anforderung <code>[PRS_E2E_00806]</code>.</li>\n<li><strong>Implementierungshinweise:</strong></li>\n<li>Entwickler müssen beachten, dass die textuelle Beschreibung „bits 0 and 1 in Big Endian order“ sich direkt in der C-äquivalenten Bitmaskierungs- und Shift-Operation <code>(Data[Offset+20] &amp; 0x3F) | ((messageType &amp; 0x03) &lt;&lt; 6)</code> widerspiegelt, wobei Bit 0 dem MSB (Wertigkeit <code>0x80</code>) und Bit 1 der Wertigkeit <code>0x40</code> entspricht.</li>\n<li>Etwaige zuvor in <code>Data[Offset+20]</code> an den Bits 2 bis 7 enthaltene Daten (wie z. B. Message Result oder SourceID-Anteile) bleiben durch die Maskierung mit <code>0x3F</code> unverändert erhalten.</li>\n</ul>"}], "trans": [{"from": "FIG-a58e080597ac3e16", "to": "FIG-233c3604ea61634a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
